{
  "name": "opencode-worktrunk-workspaces",
  "version": "0.1.0",
  "description": "Worktrunk-backed workspace adaptor for OpenCode",
  "type": "module",
  "homepage": "https://github.com/Alergeek-Ventures/opencode-worktrunk-workspaces#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Alergeek-Ventures/opencode-worktrunk-workspaces.git"
  },
  "bugs": {
    "url": "https://github.com/Alergeek-Ventures/opencode-worktrunk-workspaces/issues"
  },
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "worktrunk",
    "git-worktree"
  ],
  "exports": {
    ".": "./dist/index.js"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  },
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.0"
  },
  "dependencies": {
    "zod": "^4.1.11"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.14.17",
    "@types/node": "^24.6.0",
    "typescript": "^5.9.3"
